<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { HammerIcon, CheckCircle2Icon, AlertCircleIcon, ChevronDownIcon, ChevronUpIcon, Loader2Icon } from 'lucide-vue-next';
import { ref, watch, onMounted, nextTick, inject, computed, markRaw } from 'vue';
import type { CombinedToolCall } from '@/01-models/types';
import { storageService } from '@/00-storage/service';
import { useToolCallOutput } from '@/composables/chat/ui/useToolCallOutput';
import ShellExecuteToolCall from './ShellExecuteToolCall.vue';
import type { BinaryObjectId } from '@/01-models/ids';

const props = defineProps<{
  toolCall: CombinedToolCall,
}>();

const inSequence = inject<boolean>('inSequence', false);
const toolCallOutput = useToolCallOutput();

type DetailState = 'collapsed' | 'preview' | 'expanded';

// Inside a sequence: start in preview (height-limited).
// Outside a sequence: start expanded (original behaviour).
const detailState = ref<DetailState>(inSequence ? 'preview' : 'expanded');

const isDetailVisible = computed(() => detailState.value !== 'collapsed');
const isPreview = computed(() => detailState.value === 'preview');

const detailsRef = ref<HTMLElement | null>(null);
const isPreviewOverflowing = ref(false);

const binaryContent = ref<string | null>(null);
const isLoadingBinary = ref(false);

const resolveBinary = async () => {
  const result = props.toolCall.result;
  let binaryId: BinaryObjectId | null = null;

  if (result.status === 'success' && result.content.type === 'binary_object') {
    binaryId = result.content.id;
  } else if (result.status === 'error' && result.error.message.type === 'binary_object') {
    binaryId = result.error.message.id;
  }

  if (binaryId && !binaryContent.value && !isLoadingBinary.value) {
    isLoadingBinary.value = true;
    try {
      const blob = await storageService.getFile({ binaryObjectId: binaryId });
      if (blob) {
        binaryContent.value = await blob.text();
      }
    } catch (e) {
      console.error('Failed to load binary tool content:', e);
      binaryContent.value = '[Error: Failed to load content]';
    } finally {
      isLoadingBinary.value = false;
    }
  }
};

function checkPreviewOverflow() {
  if (!detailsRef.value || detailState.value !== 'preview') {
    isPreviewOverflowing.value = false;
    return;
  }
  isPreviewOverflowing.value = detailsRef.value.scrollHeight > detailsRef.value.clientHeight;
}

watch(() => props.toolCall.result, resolveBinary, { immediate: true });
watch([binaryContent, isLoadingBinary], async () => {
  await nextTick();
  checkPreviewOverflow();
});
watch(detailState, async () => {
  await nextTick();
  checkPreviewOverflow();
});
onMounted(async () => {
  await resolveBinary();
  await nextTick();
  checkPreviewOverflow();
});

// Header click: collapse if visible, expand (skip preview) if collapsed.
function handleHeaderClick() {
  switch (detailState.value) {
  case 'collapsed':
    detailState.value = 'expanded';
    break;
  case 'preview':
  case 'expanded':
    detailState.value = 'collapsed';
    break;
  default: {
    const _ex: never = detailState.value;
    throw new Error(`Unhandled detail state: ${_ex}`);
  }
  }
}

// Returns a specialized display component for known tool names, or null to use generic rendering.
const specializedContent = computed(() => {
  switch (props.toolCall.call.function.name) {
  case 'shell_execute': return markRaw(ShellExecuteToolCall);
  default: return null;
  }
});

const liveOutput = computed(() => {
  return toolCallOutput.getOutput({
    toolCallId: props.toolCall.id,
    status: props.toolCall.result.status,
  }).value;
});

// Content area click in preview: expand fully.
function handlePreviewClick() {
  detailState.value = 'expanded';
}

const formatArgs = ({ args }: { args: string | Record<string, unknown> }): string => {
  if (typeof args === 'string') {
    try {
      return JSON.stringify(JSON.parse(args), null, 2);
    } catch (e) {
      return args;
    }
  }
  try {
    return JSON.stringify(args, null, 2);
  } catch (e) {
    return String(args);
  }
};

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      detailState,
      handleHeaderClick,
      handlePreviewClick,
      // Backward compat for existing tests
      isExpanded: isDetailVisible,
      toggleExpand: handleHeaderClick,
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/078aabb5e36aeb6304d0857b80c9050900cf989760273e90de5585d0b5777aa7.js";
import "virtual:naidan-tailwind-css-module/0925f8bb339b4a5bd6925e08ded11b56fb0f093eb8b339d79d1b4e7628f96f43.js";
import "virtual:naidan-tailwind-css-module/101edd00ea527063059f1fbba5b60f28c8ebde6b9eb15cfc63d6544cd4092d68.js";
import "virtual:naidan-tailwind-css-module/1467faa67f2e1854474547fd2dad2da1c52018e938e15e1166528fb49bfec94f.js";
import "virtual:naidan-tailwind-css-module/157eb0a4bdd803cd7c8ee5516d10820b5774cd818df4bf345ac81496ae198f00.js";
import "virtual:naidan-tailwind-css-module/4e6dbd5ff01434af16b6fa5d12aa6f52eea42a49719ea298d9e1c66deeadc590.js";
import "virtual:naidan-tailwind-css-module/69d3f89da3142837a4bf41b7a4d41941850c442adf8f9f43ef7bb05b3728dd83.js";
import "virtual:naidan-tailwind-css-module/6b507d92345c2d1bfbf9a04a3c1a4ce099347e17123e2463560f4fa48bf58770.js";
import "virtual:naidan-tailwind-css-module/8ad986ada112e9edc96feee653d52ed22276f22272ec9b65497884a85606c0f7.js";
import "virtual:naidan-tailwind-css-module/bc52073a8fbbdd5ce14ae456914da0023cc8561fa18f9feb9407e0dee986813a.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
import "virtual:naidan-tailwind-css-module/fc367e3c7dbf14bf04d21f6499872e164ee2c6656a0b4c4650412d7ed61dc727.js";
</script>

<template>
  <div
    :tw-class="['group/tool border rounded-xl overflow-hidden transition-all duration-300 shadow-sm mb-2 last:mb-0',
                toolCall.result.status === 'executing' ? 'bg-blue-50/20 border-blue-100/30 dark:bg-blue-900/10 dark:border-blue-800/20' : '',
                toolCall.result.status === 'success' ? 'bg-white/50 dark:bg-gray-800/30 border-gray-100/50 dark:border-gray-700/30' : '',
                toolCall.result.status === 'error' ? 'bg-red-50/20 border-red-100/30 dark:bg-red-900/10 dark:border-red-800/20' : ''
    ]"
    data-testid="lm-tool-call"
  >
    <!-- Tool Header -->
    <div
      @click="handleHeaderClick"
      tw-class="flex items-center justify-between px-3 py-1.5 cursor-pointer hover:bg-black/5 dark:hover:bg-white/5 transition-colors"
    >
      <div tw-class="flex items-center gap-2.5">
        <div :tw-class="['p-1 rounded-lg',
                         toolCall.result.status === 'executing' ? 'bg-blue-100/50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400' : '',
                         toolCall.result.status === 'success' ? 'bg-gray-100 dark:bg-gray-700/50 text-gray-500 dark:text-gray-400' : '',
                         toolCall.result.status === 'error' ? 'bg-red-100/50 dark:bg-red-900/30 text-red-600 dark:text-red-400' : ''
        ]">
          <HammerIcon v-if="toolCall.result.status === 'executing'" tw-class="w-3 h-3 animate-bounce" />
          <CheckCircle2Icon v-else-if="toolCall.result.status === 'success'" tw-class="w-3 h-3" />
          <AlertCircleIcon v-else tw-class="w-3 h-3" />
        </div>

        <div tw-class="flex flex-col">
          <span :tw-class="['text-[10px] font-bold capitalize tracking-wider',
                            toolCall.result.status === 'executing' ? 'text-blue-700 dark:text-blue-300' : 'text-gray-500 dark:text-gray-400'
          ]">
            {{ toolCall.call.function.name }}
          </span>
          <span v-if="toolCall.result.status === 'executing'" tw-class="text-[9px] text-blue-600/70 dark:text-blue-400/70 animate-pulse">
            {{ lazyStrings.toolCall__executing() }}
          </span>
        </div>
      </div>

      <button tw-class="p-1 text-gray-400 group-hover/tool:text-gray-600 dark:group-hover/tool:text-gray-300 transition-colors">
        <ChevronUpIcon v-if="isDetailVisible" tw-class="w-3.5 h-3.5" />
        <ChevronDownIcon v-else tw-class="w-3.5 h-3.5" />
      </button>
    </div>

    <!-- Tool Details (Expandable) -->
    <Transition
      tw-enter-active-class="transition-all duration-300 ease-out"
      tw-leave-active-class="transition-all duration-200 ease-in"
      tw-enter-from-class="max-h-0 opacity-0"
      tw-enter-to-class="max-h-[1500px] opacity-100"
      tw-leave-from-class="max-h-[1500px] opacity-100"
      tw-leave-to-class="max-h-0 opacity-0"
    >
      <div v-if="isDetailVisible" tw-class="border-t border-inherit overflow-hidden">
        <!-- Preview wrapper: height-limited, entire area clickable to expand -->
        <div
          v-if="isPreview"
          ref="detailsRef"
          tw-class="relative max-h-40 overflow-hidden cursor-pointer"
          data-testid="tool-detail-preview"
          @click="handlePreviewClick"
        >
          <div tw-class="p-3 flex flex-col gap-3">
            <component
              v-if="specializedContent"
              :is="specializedContent"
              :args="toolCall.call.function.arguments"
              :result="toolCall.result"
              :live-output="liveOutput"
            />
            <template v-else>
              <!-- Arguments -->
              <div>
                <div tw-class="text-[9px] font-bold text-gray-400 uppercase tracking-tight mb-1">{{ lazyStrings.toolCall__arguments() }}</div>
                <pre class="custom-scrollbar" tw-class="text-[10px] font-mono p-2 bg-black/5 dark:bg-black/20 rounded-lg overflow-x-auto">{{ formatArgs({ args: toolCall.call.function.arguments }) }}</pre>
              </div>

              <!-- Result -->
              <div v-if="toolCall.result.status === 'executing' && liveOutput">
                <div tw-class="text-[9px] font-bold text-gray-400 uppercase tracking-tight mb-1">{{ lazyStrings.toolCall__live_output() }}</div>
                <pre tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-blue-500/5 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{{ liveOutput }}</pre>
              </div>
              <div v-else-if="toolCall.result.status !== 'executing'">
                <div tw-class="text-[9px] font-bold text-gray-400 uppercase tracking-tight mb-1">
                  {{ toolCall.result.status === 'success' ? lazyStrings.toolCall__result() : lazyStrings.toolCall__error() }}
                </div>
                <template v-if="toolCall.result.status === 'success'">
                  <div v-if="toolCall.result.content.type === 'text'"
                       tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-green-500/5 text-gray-700 dark:text-gray-300 whitespace-pre-wrap"
                  >{{ toolCall.result.content.text }}</div>
                  <div v-else tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-green-500/5 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{{ binaryContent }}</div>
                </template>
                <template v-else-if="toolCall.result.status === 'error'">
                  <div tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-red-500/5 text-red-600 dark:text-red-400">
                    <div tw-class="font-bold mb-1 uppercase text-[8px] tracking-widest opacity-70">{{ lazyStrings.toolCall__code() }} {{ toolCall.result.error.code }}</div>
                    <div v-if="toolCall.result.error.message.type === 'text'" tw-class="whitespace-pre-wrap">{{ toolCall.result.error.message.text }}</div>
                    <div v-else tw-class="whitespace-pre-wrap">{{ binaryContent }}</div>
                  </div>
                </template>
              </div>
            </template>
          </div>

          <!-- Bottom fade hint when content overflows -->
          <div
            v-if="isPreviewOverflowing"
            tw-class="absolute bottom-0 left-0 right-0 h-10 bg-gradient-to-t from-white dark:from-gray-800 to-transparent pointer-events-none"
            data-testid="tool-detail-overflow-hint"
          />
        </div>

        <!-- Expanded: full content, no height limit -->
        <div v-else tw-class="p-3 flex flex-col gap-3">
          <component
            v-if="specializedContent"
            :is="specializedContent"
            :args="toolCall.call.function.arguments"
            :result="toolCall.result"
            :live-output="liveOutput"
          />
          <template v-else>
            <!-- Arguments -->
            <div>
              <div tw-class="text-[9px] font-bold text-gray-400 uppercase tracking-tight mb-1">{{ lazyStrings.toolCall__arguments() }}</div>
              <pre class="custom-scrollbar" tw-class="text-[10px] font-mono p-2 bg-black/5 dark:bg-black/20 rounded-lg overflow-x-auto">{{ formatArgs({ args: toolCall.call.function.arguments }) }}</pre>
            </div>

            <!-- Result -->
            <div v-if="toolCall.result.status === 'executing' && liveOutput">
              <div tw-class="text-[9px] font-bold text-gray-400 uppercase tracking-tight mb-1">{{ lazyStrings.toolCall__live_output() }}</div>
              <pre tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-blue-500/5 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{{ liveOutput }}</pre>
            </div>
            <div v-else-if="toolCall.result.status !== 'executing'">
              <div tw-class="text-[9px] font-bold text-gray-400 uppercase tracking-tight mb-1">
                {{ toolCall.result.status === 'success' ? lazyStrings.toolCall__result() : lazyStrings.toolCall__error() }}
              </div>

              <div v-if="isLoadingBinary" tw-class="flex items-center gap-2 p-3 bg-gray-50 dark:bg-gray-800/50 rounded-lg text-gray-400">
                <Loader2Icon tw-class="w-3.5 h-3.5 animate-spin" />
                <span tw-class="text-[10px] font-medium">{{ lazyStrings.toolCall__loading_large_result() }}</span>
              </div>

              <template v-else-if="toolCall.result.status === 'success'">
                <div v-if="toolCall.result.content.type === 'text'"
                     tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-green-500/5 text-gray-700 dark:text-gray-300 whitespace-pre-wrap"
                >
                  {{ toolCall.result.content.text }}
                </div>
                <div v-else tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-green-500/5 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
                  {{ binaryContent }}
                </div>
              </template>

              <template v-else-if="toolCall.result.status === 'error'">
                <div tw-class="text-[10px] font-mono p-2 rounded-lg break-words bg-red-500/5 text-red-600 dark:text-red-400">
                  <div tw-class="font-bold mb-1 uppercase text-[8px] tracking-widest opacity-70">{{ lazyStrings.toolCall__code() }} {{ toolCall.result.error.code }}</div>
                  <div v-if="toolCall.result.error.message.type === 'text'" tw-class="whitespace-pre-wrap">{{ toolCall.result.error.message.text }}</div>
                  <div v-else tw-class="whitespace-pre-wrap">{{ binaryContent }}</div>
                </div>
              </template>
            </div>
          </template>
        </div>
      </div>
    </Transition>
  </div>
</template>

