<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { ref, computed, provide, nextTick } from 'vue';
import { Loader2Icon, EyeIcon, EyeOffIcon, BirdIcon } from 'lucide-vue-next';
import type { ChatFlowItem, FlowMetadata, SequenceStats } from '@/composables/useChatDisplayFlow';

const props = withDefaults(defineProps<{
  items: ChatFlowItem[],
  isProcessing: boolean,
  flow?: FlowMetadata,
  stats?: SequenceStats,
  isFirstInTurn?: boolean,
}>(), {
  flow: () => ({ position: 'standalone', nesting: 'none' }),
  stats: () => ({
    thinkingSteps: 0,
    toolCallCount: 0,
    toolNames: [],
    isCurrentlyThinking: false,
    isCurrentlyToolRunning: false,
    isWaiting: false,
  }),
  isFirstInTurn: false,
});

const isExpanded = ref(false);
const toggleRef = ref<HTMLElement | null>(null);

provide('inSequence', true);

async function toggle() {
  const wasExpanded = isExpanded.value;
  isExpanded.value = !wasExpanded;
  // When collapsing, scroll the toggle back into view so the user
  // doesn't end up at the bottom of the now-hidden content.
  if (wasExpanded) {
    await nextTick();
    toggleRef.value?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

const displaySummary = computed(() => {
  const parts: string[] = [];
  if (props.stats.thinkingSteps > 0) {
    const thinkingSteps = lazyStrings.AssistantProcessSequence__thinking_steps({ count: props.stats.thinkingSteps });
    if (thinkingSteps === undefined) return undefined;
    parts.push(thinkingSteps);
  }
  if (props.stats.toolCallCount > 0) {
    const toolExecutions = lazyStrings.AssistantProcessSequence__tool_executions({ count: props.stats.toolCallCount });
    if (toolExecutions === undefined) return undefined;
    parts.push(toolExecutions);
  }
  if (props.stats.toolNames.length > 0) {
    const displayedToolNames = props.stats.toolNames.slice(0, 2);
    const usedTools = lazyStrings.AssistantProcessSequence__used_tools({ toolNames: displayedToolNames.join(', ') });
    if (usedTools === undefined) return undefined;
    let toolSummary = usedTools;
    if (props.stats.toolNames.length > displayedToolNames.length) {
      const moreTools = lazyStrings.AssistantProcessSequence__and_more({ count: props.stats.toolNames.length - displayedToolNames.length });
      if (moreTools === undefined) return undefined;
      toolSummary += ` ${moreTools}`;
    }
    parts.push(toolSummary);
  }
  if (parts.length > 0) return parts.join(' • ');
  return lazyStrings.AssistantProcessSequence__process_details();
});

const modelId = computed(() => {
  const first = props.items[0];
  if (!first) return undefined;
  const type = first.type;
  switch (type) {
  case 'message':
    return first.node.modelId;
  case 'tool_group':
    return first.node.modelId;
  case 'process_sequence':
    return undefined;
  default: {
    const _ex: never = type;
    return _ex;
  }
  }
});

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      isExpanded,
      toggle,
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/08a43c2f58dfa5254b7a9da43426be59e5ceb8cd78777e48ecb5bcc45c17cef9.js";
import "virtual:naidan-tailwind-css-module/1a70e7226a0b06d8f0d89378c6575eeec72a456c15402cb83ddc1dff9ad74977.js";
import "virtual:naidan-tailwind-css-module/5b33de7a23d23ffe375bebbfe2be35862d78e938df7f7a30f4a28f6e08f496fb.js";
import "virtual:naidan-tailwind-css-module/69d3f89da3142837a4bf41b7a4d41941850c442adf8f9f43ef7bb05b3728dd83.js";
import "virtual:naidan-tailwind-css-module/8fd02b1ebaa72af84dad0cb8e058f899cf634dbf2905d615188c770db85abe59.js";
import "virtual:naidan-tailwind-css-module/9b55c9c2041a7178c87de6025f85124e29799512ad0b3520824b32bceb8160a7.js";
import "virtual:naidan-tailwind-css-module/b521e235b4efb22b5e330a04e4d91f8c39b2c049a3cdff309119a66c11397e7d.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
</script>

<template>
  <div
    class="assistant-process-sequence"
    :tw-class="['min-w-0 max-w-full flex flex-col transition-all duration-300 bg-gray-50/30 dark:bg-gray-800/20',
                (flow.position === 'standalone' || flow.position === 'start') ? 'border-t border-gray-100 dark:border-gray-800/50 pt-1.5' : 'pt-0',
                (flow.position === 'standalone' || flow.position === 'end') ? 'border-b border-gray-100 dark:border-gray-800/50' : ''
    ]"
  >
    <!-- Turn Header (Icon + Model ID) -->
    <div v-if="isFirstInTurn" tw-class="min-w-0 flex items-center gap-3 mb-1 px-5 pt-3">
      <div tw-class="w-8 h-8 shrink-0 rounded-xl flex items-center justify-center shadow-sm border border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800">
        <BirdIcon tw-class="w-4 h-4 text-blue-600 dark:text-blue-400" />
      </div>
      <div tw-class="min-w-0 text-[10px] font-bold text-gray-400 dark:text-gray-500 flex items-center gap-2">
        <span tw-class="truncate" :title="modelId">{{ modelId || lazyStrings.SHARED__assistant() }}</span>
      </div>
    </div>

    <!-- Compact Show/Less Toggle -->
    <div ref="toggleRef" :tw-class="['px-5 py-1', isExpanded ? 'sticky top-0 z-10 bg-gray-50/80 dark:bg-gray-800/80 backdrop-blur-sm' : '']">
      <button
        type="button"
        :aria-expanded="isExpanded"
        :title="displaySummary"
        @click="toggle"
        :tw-class="['inline-flex min-w-0 max-w-full items-center gap-2 px-2.5 py-1 transition-all duration-200 group/seq cursor-pointer rounded-lg border shadow-sm select-none',
                    isExpanded
                      ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-200/60 dark:border-blue-800/60 text-blue-700 dark:text-blue-300'
                      : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-400 dark:text-gray-500 hover:border-blue-300 dark:hover:border-blue-700 hover:text-blue-600'
        ]"
        data-testid="assistant-process-toggle"
      >
        <!-- Status/Action Icon -->
        <span tw-class="flex-shrink-0">
          <Loader2Icon v-if="isProcessing && (stats.isCurrentlyThinking || stats.isCurrentlyToolRunning || stats.isWaiting)" tw-class="w-3 h-3 animate-spin text-blue-500/70" data-testid="icon-loader" />
          <component :is="isExpanded ? EyeOffIcon : EyeIcon" v-else :tw-class="['w-3 h-3 transition-transform duration-300', { 'opacity-60': !isExpanded }]" />
        </span>

        <!-- Summary Text -->
        <span tw-class="min-w-0 text-left text-[10px] leading-relaxed font-bold tracking-tight whitespace-normal [overflow-wrap:anywhere]">
          {{ displaySummary }}
        </span>

        <!-- Action Label -->
        <span tw-class="shrink-0 text-[8px] uppercase font-black tracking-tighter opacity-0 group-hover/seq:opacity-100 transition-opacity pl-1 border-l border-current/10 ml-0.5">
          {{ isExpanded ? lazyStrings.AssistantProcessSequence__less() : lazyStrings.AssistantProcessSequence__show() }}
        </span>
      </button>
      <slot v-if="!isExpanded && isProcessing && !stats.isCurrentlyThinking && !stats.isWaiting" name="cursor" />
    </div>

    <!-- Peek Slot (During processing) -->
    <div
      v-if="!isExpanded && isProcessing && (stats.isCurrentlyThinking || stats.isWaiting)"
      class="animate-in fade-in slide-in-from-top-1" tw-class="px-5 pb-2 pt-0.5 duration-300"
    >
      <div tw-class="bg-white/40 dark:bg-gray-800/40 rounded-lg border border-blue-100/30 dark:border-blue-900/20 p-0.5">
        <slot name="peek" />
      </div>
      <slot name="cursor" />
    </div>

    <!-- Expanded Content -->
    <div
      :tw-class="['grid transition-[grid-template-rows] duration-500 ease-in-out', isExpanded ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]']"
    >
      <div tw-class="min-h-0 overflow-hidden">
        <div class="animate-in fade-in" tw-class="pb-3 pt-1 duration-500">
          <slot :is-expanded="isExpanded" />
          <div v-if="isExpanded && isProcessing" tw-class="px-5 mt-1">
            <slot name="cursor" />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped>
.min-h-0 {
  min-height: 0;
}
</style>

