<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { SquareIcon, SparklesIcon, ChevronDownIcon, ChevronUpIcon, CheckCircle2Icon, XCircleIcon } from 'lucide-vue-next';
import type { ContextCompactProgress } from '@/logic/context-compact';
import { toContextCompactDisplayProgress } from '@/logic/context-compact';

const props = defineProps<{
  progress: ContextCompactProgress,
}>();

defineEmits<{
  (e: 'abort'): void,
}>();

const display = computed(() => {
  const progressDisplay = toContextCompactDisplayProgress({
    progress: props.progress,
    nowMs: Date.now(),
  });
  const copy = (() => {
    switch (props.progress.phase) {
    case 'idle':
      return { title: '', detail: '' };
    case 'preparing':
      return {
        title: lazyStrings.contextCompact__compacting_context(),
        detail: lazyStrings.contextCompact__preparing_messages_and_keeping_recent_messages({
          compactedMessageCount: props.progress.compactedMessageCount,
          suffixMessageCount: props.progress.suffixMessageCount,
        }),
      };
    case 'building_request':
      return {
        title: lazyStrings.contextCompact__compacting_context(),
        detail: lazyStrings.contextCompact__building_compact_request(),
      };
    case 'requesting_model':
      return {
        title: lazyStrings.contextCompact__compacting_context(),
        detail: lazyStrings.contextCompact__waiting_for_the_model(),
      };
    case 'receiving_compact':
      return {
        title: lazyStrings.contextCompact__compacting_context(),
        detail: lazyStrings.contextCompact__generating_compact_context_with_characters_received({
          outputChars: props.progress.outputChars,
        }),
      };
    case 'applying_branch':
      return {
        title: lazyStrings.contextCompact__compacting_context(),
        detail: lazyStrings.contextCompact__applying_compact_branch(),
      };
    case 'complete':
      return {
        title: lazyStrings.contextCompact__compacting_context(),
        detail: lazyStrings.contextCompact__complete(),
      };
    case 'failed':
      return {
        title: lazyStrings.contextCompact__compacting_context_failed(),
        detail: props.progress.message,
      };
    case 'aborted':
      return {
        title: lazyStrings.contextCompact__compacting_context(),
        detail: lazyStrings.contextCompact__aborted(),
      };
    default: {
      const _ex: never = props.progress;
      throw new Error(`Unhandled context compact copy phase: ${_ex}`);
    }
    }
  })();

  return {
    ...progressDisplay,
    ...copy,
  };
});

const visibleDisplay = ref(display.value);
const shouldRender = ref(display.value.isRunning);
const animatedPercent = ref(0);
const hideTimerId = ref<number | undefined>(undefined);
const animationFrameId = ref<number | undefined>(undefined);

function clearHideTimer() {
  if (hideTimerId.value !== undefined) {
    window.clearTimeout(hideTimerId.value);
    hideTimerId.value = undefined;
  }
}

function clearPercentAnimationFrame() {
  if (animationFrameId.value !== undefined) {
    window.cancelAnimationFrame(animationFrameId.value);
    animationFrameId.value = undefined;
  }
}

function animatePercentTo({
  percent,
}: {
  percent: number,
}) {
  clearPercentAnimationFrame();
  animationFrameId.value = window.requestAnimationFrame(() => {
    animatedPercent.value = percent;
    animationFrameId.value = undefined;
  });
}

watch(display, async (nextDisplay) => {
  clearHideTimer();
  visibleDisplay.value = nextDisplay;

  if (nextDisplay.isRunning) {
    shouldRender.value = true;
    await nextTick();
    animatePercentTo({ percent: nextDisplay.percent });
    return;
  }

  switch (props.progress.phase) {
  case 'complete':
  case 'failed':
  case 'aborted':
    shouldRender.value = true;
    await nextTick();
    animatePercentTo({ percent: nextDisplay.percent });
    hideTimerId.value = window.setTimeout(() => {
      shouldRender.value = false;
      hideTimerId.value = undefined;
    }, 300);
    return;
  case 'idle':
    shouldRender.value = false;
    animatedPercent.value = 0;
    return;
  case 'preparing':
  case 'building_request':
  case 'requesting_model':
  case 'receiving_compact':
  case 'applying_branch':
    shouldRender.value = true;
    return;
  default: {
    const _ex: never = props.progress;
    throw new Error(`Unhandled compact progress visibility phase: ${_ex}`);
  }
  }
}, { immediate: true });

const requestPreview = computed(() => {
  switch (props.progress.phase) {
  case 'building_request':
  case 'requesting_model':
  case 'receiving_compact':
  case 'applying_branch':
  case 'complete':
    return props.progress.requestPreview;
  case 'idle':
  case 'preparing':
  case 'failed':
  case 'aborted':
    return undefined;
  default: {
    const _ex: never = props.progress;
    throw new Error(`Unhandled compact progress preview phase: ${_ex}`);
  }
  }
});

const outputPreview = computed(() => {
  switch (props.progress.phase) {
  case 'receiving_compact':
  case 'applying_branch':
  case 'complete':
    return props.progress.outputPreview;
  case 'idle':
  case 'preparing':
  case 'building_request':
  case 'requesting_model':
  case 'failed':
  case 'aborted':
    return undefined;
  default: {
    const _ex: never = props.progress;
    throw new Error(`Unhandled compact output preview phase: ${_ex}`);
  }
  }
});

const showRequestPreview = ref(false);
const requestPreviewRef = ref<HTMLElement | null>(null);
const outputPreviewRef = ref<HTMLElement | null>(null);
const shouldAutoScrollOutput = ref(true);

function syncOutputAutoScrollState() {
  const element = outputPreviewRef.value;
  if (!element) {
    return;
  }

  const thresholdPx = 12;
  shouldAutoScrollOutput.value = element.scrollTop + element.clientHeight >= element.scrollHeight - thresholdPx;
}

function scrollOutputToBottom() {
  const element = outputPreviewRef.value;
  if (!element) {
    return;
  }

  element.scrollTop = element.scrollHeight;
}

function scrollRequestToBottom() {
  const element = requestPreviewRef.value;
  if (!element) {
    return;
  }

  element.scrollTop = element.scrollHeight;
}

watch(showRequestPreview, async (val) => {
  if (val) {
    await nextTick();
    scrollRequestToBottom();
  }
});

watch(outputPreview, async () => {
  if (!shouldAutoScrollOutput.value) {
    return;
  }

  await nextTick();
  scrollOutputToBottom();
});

watch(requestPreview, async () => {
  if (!showRequestPreview.value) {
    return;
  }

  await nextTick();
  scrollRequestToBottom();
});

onBeforeUnmount(() => {
  clearHideTimer();
  clearPercentAnimationFrame();
});

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      display,
      visibleDisplay,
      shouldRender,
      animatedPercent,
      requestPreview,
      outputPreview,
      shouldAutoScrollOutput,
      syncOutputAutoScrollState,
      scrollRequestToBottom,
      scrollOutputToBottom,
      showRequestPreview,
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/0963f1f2efd282a3155bf2baaf9ccb2b9bcb9e9a0bfce29d1ec552f2fc67b37d.js";
import "virtual:naidan-tailwind-css-module/1bb5dd6f410ca413e92ab502f2f281896eb4674da231e221d8df2e32bf9406e9.js";
import "virtual:naidan-tailwind-css-module/1fc352e4f4d158272aef0d689b35af08e47e1a0cb1f86097dd62891672898169.js";
import "virtual:naidan-tailwind-css-module/1fc98b1e0764836790457dde9d75f53dd245a646ec1690c6f5417619af93b907.js";
import "virtual:naidan-tailwind-css-module/3055719b12aaac824bb0a682d45cad87551c3e593161aba61846d2e48a8b96ca.js";
import "virtual:naidan-tailwind-css-module/56e4373f55f359f04f7e389d21fb97c53c3d3909904d57e24636fcec24252a4b.js";
import "virtual:naidan-tailwind-css-module/98de6fa397e05a7ac28e23a51a89adb42b114642a6df977a2fc77f9a976d25eb.js";
import "virtual:naidan-tailwind-css-module/d0871dabe15440eacdd0555ebd78d8b9101327e0e813d2806795be21a81a2dcb.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
import "virtual:naidan-tailwind-css-module/f05dbb0323e9b42b6d4ac9349fc4b03c8ae5874a519d6620c525a1b64c559e1e.js";
</script>

<template>
  <Transition
    tw-enter-active-class="transition duration-300 ease-out"
    tw-enter-from-class="transform -translate-y-4 opacity-0"
    tw-enter-to-class="transform translate-y-0 opacity-100"
    tw-leave-active-class="transition duration-200 ease-in"
    tw-leave-from-class="transform translate-y-0 opacity-100"
    tw-leave-to-class="transform -translate-y-4 opacity-0"
  >
    <div
      v-if="shouldRender"
      :tw-class="['border-b border-indigo-100/50 dark:border-indigo-900/40 bg-white/70 dark:bg-gray-950/60 backdrop-blur-md px-4 sm:px-6 py-3 shadow-sm', {
        'border-emerald-500/30 bg-emerald-50/20 dark:bg-emerald-950/10': progress.phase === 'complete',
        'border-rose-500/20 bg-rose-50/10 dark:bg-rose-950/10': progress.phase === 'failed',
        'border-amber-500/20 bg-amber-50/10 dark:bg-amber-950/10': progress.phase === 'aborted'
      }]"
      data-testid="context-compact-progress-strip"
    >
      <div tw-class="flex items-start gap-4">
        <!-- Status Icon with Glow -->
        <div tw-class="relative shrink-0 pt-1">
          <CheckCircle2Icon v-if="progress.phase === 'complete'" class="animate-in zoom-in" tw-class="w-4 h-4 text-emerald-500 dark:text-emerald-400 duration-300" />
          <XCircleIcon v-else-if="progress.phase === 'failed'" tw-class="w-4 h-4 text-rose-500 dark:text-rose-400" />
          <XCircleIcon v-else-if="progress.phase === 'aborted'" tw-class="w-4 h-4 text-amber-500 dark:text-amber-400" />
          <SparklesIcon v-else class="animate-pulse-glow" tw-class="w-4 h-4 text-indigo-500 dark:text-indigo-400" />
        </div>

        <div tw-class="min-w-0 flex-1 space-y-2">
          <!-- Header: Title & Percentage -->
          <div tw-class="flex items-center justify-between gap-3">
            <span
              class="animate-text-scan"
              :tw-class="['truncate text-[10px] font-black uppercase tracking-[0.2em] bg-gradient-to-r bg-[length:200%_auto] bg-clip-text text-transparent', {
                'from-emerald-600 via-teal-500 to-emerald-600 dark:from-emerald-400 dark:via-teal-300 dark:to-emerald-400': progress.phase === 'complete',
                'from-rose-600 via-pink-500 to-rose-600 dark:from-rose-400 dark:via-pink-300 dark:to-rose-400': progress.phase === 'failed',
                'from-amber-600 via-yellow-500 to-amber-600 dark:from-amber-400 dark:via-yellow-300 dark:to-amber-400': progress.phase === 'aborted',
                'from-indigo-600 via-violet-500 to-indigo-600 dark:from-indigo-400 dark:via-violet-300 dark:to-indigo-400': progress.phase !== 'complete' && progress.phase !== 'failed' && progress.phase !== 'aborted'
              }]"
            >
              {{ visibleDisplay.title }}
            </span>
            <span
              :tw-class="['shrink-0 text-[10px] font-black tabular-nums transition-colors duration-500', {
                'text-emerald-500 dark:text-emerald-400': progress.phase === 'complete',
                'text-rose-500 dark:text-rose-400': progress.phase === 'failed',
                'text-amber-500 dark:text-amber-400': progress.phase === 'aborted',
                'text-indigo-500/80 dark:text-indigo-400/80': progress.phase !== 'complete' && progress.phase !== 'failed' && progress.phase !== 'aborted'
              }]"
            >
              {{ animatedPercent }}%
            </span>
          </div>

          <!-- Progress Bar Container -->
          <div tw-class="relative">
            <!-- Glow background -->
            <div
              :tw-class="['absolute inset-0 rounded-full blur-[2px] transition-all duration-500 ease-out', {
                'bg-emerald-500/20 dark:bg-emerald-400/10': progress.phase === 'complete',
                'bg-indigo-500/10 dark:bg-indigo-400/5': progress.phase !== 'complete'
              }]"
              :style="{ width: `${animatedPercent}%` }"
            />

            <div
              :tw-class="['h-1.5 overflow-hidden rounded-full transition-colors duration-500 ring-1 ring-inset',
                          progress.phase === 'complete' ? 'bg-emerald-100/50 dark:bg-emerald-950/40 ring-emerald-500/10' : 'bg-indigo-100 dark:bg-gray-800 ring-indigo-500/10 dark:ring-indigo-400/10'
              ]"
            >
              <!-- Animated Gradient Bar -->
              <div
                class="animate-shimmer"
                :tw-class="['h-full rounded-full transition-all duration-500 ease-out bg-[length:200%_auto]', {
                  'bg-gradient-to-r from-emerald-500 via-teal-400 to-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]': progress.phase === 'complete',
                  'bg-rose-500': progress.phase === 'failed',
                  'bg-amber-500': progress.phase === 'aborted',
                  'bg-gradient-to-r from-blue-500 via-violet-500 to-cyan-500': progress.phase !== 'complete' && progress.phase !== 'failed' && progress.phase !== 'aborted'
                }]"
                :style="{ width: `${animatedPercent}%` }"
                data-testid="context-compact-progress-bar"
              />
            </div>
          </div>

          <!-- Detail Text -->
          <p
            :tw-class="['truncate text-[11px] font-medium transition-colors duration-500', {
              'text-emerald-700/80 dark:text-emerald-300/70': progress.phase === 'complete',
              'text-rose-700/80 dark:text-rose-300/70': progress.phase === 'failed',
              'text-amber-700/80 dark:text-amber-300/70': progress.phase === 'aborted',
              'text-indigo-700/70 dark:text-indigo-200/60': progress.phase !== 'complete' && progress.phase !== 'failed' && progress.phase !== 'aborted'
            }]"
          >
            {{ visibleDisplay.detail }}
          </p>

          <!-- Previews Area -->
          <div v-if="requestPreview || outputPreview" tw-class="pt-1 space-y-2">
            <!-- Request Toggle (Hidden by default) -->
            <div v-if="requestPreview" data-testid="context-compact-request-preview">
              <button
                tw-class="flex items-center gap-1.5 text-[9px] font-bold uppercase tracking-wider text-indigo-500/70 hover:text-indigo-600 dark:text-indigo-400/60 dark:hover:text-indigo-300 transition-colors"
                data-testid="context-compact-request-toggle"
                @click="showRequestPreview = !showRequestPreview"
              >
                <component :is="showRequestPreview ? ChevronUpIcon : ChevronDownIcon" tw-class="w-3 h-3" />
                {{ showRequestPreview ? lazyStrings.ContextCompactProgressStrip__hide_request() : lazyStrings.ContextCompactProgressStrip__show_request() }}
              </button>

              <div v-if="showRequestPreview" tw-class="mt-1.5 rounded-lg border border-indigo-100/50 bg-indigo-50/30 dark:border-indigo-900/40 dark:bg-gray-900/40 overflow-hidden">
                <pre
                  ref="requestPreviewRef"
                  tw-class="max-h-32 overflow-auto whitespace-pre-wrap break-words px-3 py-2 text-[10px] leading-relaxed font-mono text-indigo-900/80 dark:text-indigo-100/70"
                  data-testid="context-compact-request-scroll"
                >{{ requestPreview }}</pre>
              </div>
            </div>

            <!-- Output Preview (Visible by default) -->
            <div v-if="outputPreview" tw-class="rounded-lg border border-violet-200/40 bg-violet-50/30 dark:border-violet-800/20 dark:bg-gray-900/60 overflow-hidden shadow-inner ring-1 ring-violet-500/5" data-testid="context-compact-output-preview">
              <div tw-class="flex items-center gap-2 px-3 py-1.5 border-b border-violet-100/30 dark:border-violet-800/20 bg-violet-100/20 dark:bg-violet-900/10">
                <div tw-class="w-1.5 h-1.5 rounded-full bg-violet-400 animate-pulse" />
                <span tw-class="text-[9px] font-bold uppercase tracking-widest text-violet-600/80 dark:text-violet-300/60">{{ lazyStrings.ContextCompactProgressStrip__live_output() }}</span>
              </div>
              <pre
                ref="outputPreviewRef"
                tw-class="max-h-48 overflow-auto whitespace-pre-wrap break-words px-3 py-3 text-[11px] leading-relaxed font-mono text-violet-950 dark:text-violet-100/90 selection:bg-violet-200/50 dark:selection:bg-violet-500/30"
                data-testid="context-compact-output-scroll"
                @scroll="syncOutputAutoScrollState()"
              >{{ outputPreview }}</pre>
            </div>
          </div>
        </div>

        <!-- Abort Button -->
        <button
          tw-class="shrink-0 p-2 rounded-xl text-indigo-400 hover:text-rose-500 dark:text-indigo-500 dark:hover:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/20 transition-all duration-200"
          :title="lazyStrings.ContextCompactProgressStrip__abort_compact()"
          data-testid="abort-context-compact-button"
          @click="$emit('abort')"
        >
          <SquareIcon tw-class="w-4 h-4 fill-current opacity-70" />
        </button>
      </div>
    </div>
  </Transition>
</template>

