<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { ref, computed, inject } from 'vue';
import { ShapesIcon, BirdIcon } from 'lucide-vue-next';
import { idToRaw } from '@/01-models/ids';
import type { CombinedToolCall } from '@/01-models/types';
import type { FlowMetadata } from '@/composables/useChatDisplayFlow';
import ToolCallItem from './ToolCallItem.vue';

const props = withDefaults(defineProps<{
  toolCalls: CombinedToolCall[],
  flow?: FlowMetadata,
  isFirstInTurn?: boolean,
}>(), {
  flow: () => ({ position: 'standalone', nesting: 'none' }),
  isFirstInTurn: false,
});

const inSequence = inject<boolean>('inSequence', false);

// Auto-expand inside a sequence so tool details are visible (height-limited by ToolCallItem)
const isExpanded = ref(inSequence);

const toggleExpand = () => {
  isExpanded.value = !isExpanded.value;
};

const toolNamesDisplay = computed(() => {
  const names = props.toolCalls.map(tc => tc.call.function.name);
  const limit = 3;
  const displayedNames = names.slice(0, limit);
  const remainingCount = names.length - limit;

  return lazyStrings.ToolCallGroupItem__used_tools({
    toolNames: displayedNames,
    remainingCount,
  });
});

const isNested = computed(() => props.flow.nesting === 'inside-group');

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      isExpanded,
      toggleExpand,
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/1467faa67f2e1854474547fd2dad2da1c52018e938e15e1166528fb49bfec94f.js";
import "virtual:naidan-tailwind-css-module/14c0c0ba32aa3c3b79f85a61ae6f108f23b2d0c65046131dcb6b1d430753b880.js";
import "virtual:naidan-tailwind-css-module/5b33de7a23d23ffe375bebbfe2be35862d78e938df7f7a30f4a28f6e08f496fb.js";
import "virtual:naidan-tailwind-css-module/942f36d832bedce92c49696bf7ad4d374cf79d11e88ce3f6ddc9d0eac79984d5.js";
import "virtual:naidan-tailwind-css-module/9b55c9c2041a7178c87de6025f85124e29799512ad0b3520824b32bceb8160a7.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <div
    v-if="toolCalls.length > 0"
    :tw-class="['flex flex-col transition-colors',
                !isNested ? 'bg-gray-50/30 dark:bg-gray-800/20' : '',
                (!isNested && (flow.position === 'standalone' || flow.position === 'start')) ? 'border-t border-gray-100 dark:border-gray-800/50 pt-4' : 'pt-2',
                (!isNested && (flow.position === 'standalone' || flow.position === 'end')) ? 'border-b border-gray-100 dark:border-gray-800/50' : '',
                isNested ? 'pb-2' : ''
    ]"
    data-testid="tool-call-group"
  >
    <!-- Turn Header (Icon + Model ID) -->
    <div v-if="isFirstInTurn && !isNested" tw-class="flex items-center gap-3 mb-1 px-5 pt-1 pb-2">
      <div tw-class="w-8 h-8 rounded-xl flex items-center justify-center shadow-sm border border-gray-100 dark:border-gray-700 bg-white dark:bg-gray-800">
        <BirdIcon tw-class="w-4 h-4 text-blue-600 dark:text-blue-400" />
      </div>
      <div tw-class="text-[10px] font-bold text-gray-400 dark:text-gray-500 flex items-center gap-2">
        <span>{{ lazyStrings.SHARED__assistant() }}</span>
      </div>
    </div>

    <div :tw-class="['px-5', (!isNested && (flow.position === 'standalone' || flow.position === 'end')) ? 'pb-3' : 'pb-2']">      <div
      @click="toggleExpand"
      :tw-class="['transition-all duration-500 ease-in-out relative group/tool-group w-full cursor-pointer overflow-hidden border shadow-sm',
                  /* Shape & Background */
                  isExpanded
                    ? 'p-5 rounded-2xl bg-gradient-to-br from-blue-50/50 to-sky-50/50 dark:from-blue-950/20 dark:to-sky-950/20 border-blue-100/50 dark:border-blue-800/30 shadow-inner'
                    : 'px-3 py-1.5 rounded-xl bg-white dark:bg-gray-800/50 border-blue-100/50 dark:border-blue-800/30 hover:border-blue-200 dark:hover:border-blue-800'
      ]"
    >
      <!-- Header -->
      <div
        data-testid="tool-call-group-header"
        :tw-class="['flex items-center gap-2 text-[10px] font-bold transition-colors tracking-wider relative z-20',
                    isExpanded
                      ? 'mb-2 text-blue-600 dark:text-blue-400'
                      : 'text-gray-500 dark:text-gray-400 group-hover/tool-group:text-blue-600'
        ]"
      >
        <ShapesIcon tw-class="w-3.5 h-3.5" />
        <span>{{ isExpanded ? lazyStrings.toolCall__hide_tool_executions() : toolNamesDisplay }}</span>
      </div>

      <!-- Content -->
      <Transition
        tw-enter-active-class="transition-all duration-300 ease-out"
        tw-leave-active-class="transition-all duration-200 ease-in"
        tw-enter-from-class="opacity-0 translate-y-[-10px]"
        tw-enter-to-class="opacity-100 translate-y-0"
        tw-leave-from-class="opacity-100 translate-y-0"
        tw-leave-to-class="opacity-0 translate-y-[-10px]"
      >
        <div v-if="isExpanded" class="animate-in fade-in slide-in-from-top-1" tw-class="mt-1 duration-200" @click.stop>
          <div tw-class="flex flex-col gap-3">
            <ToolCallItem
              v-for="tc in toolCalls"
              :key="idToRaw({ id: tc.nodeId })"
              :tool-call="tc"
            />
          </div>
        </div>
      </Transition>
    </div>
    </div>
  </div>
</template>
