<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { ref, onMounted, onUnmounted, computed } from 'vue';
import { transformersJsService } from '@/features/transformers-js';
import { BrainCircuitIcon, AlertTriangleIcon, ShieldCheckIcon } from 'lucide-vue-next';

const props = defineProps<{
  mode?: 'full' | 'compact',
}>();

const status = ref(transformersJsService.getState().status);
const progress = ref(transformersJsService.getState().progress);
const error = ref(transformersJsService.getState().error);
const isLoadingFromCache = ref(transformersJsService.getState().isLoadingFromCache);
const loadingModelId = ref(transformersJsService.getState().loadingModelId);

let unsubscribe: (() => void) | null = null;

onMounted(() => {
  unsubscribe = transformersJsService.subscribe({
    listener: ({ status: s, progress: p, error: e, isLoadingFromCache: l, loadingModelId: lm }) => {
      status.value = s;
      progress.value = p;
      error.value = e;
      isLoadingFromCache.value = l;
      loadingModelId.value = lm;
    },
  });
});

onUnmounted(() => {
  if (unsubscribe) unsubscribe();
});

const statusText = computed(() => {
  const currentStatus = status.value;
  switch (currentStatus) {
  case 'error':
    return lazyStrings.TransformersJsLoadingIndicator__transformers_js_error();
  case 'loading': {
    const modelName = loadingModelId.value?.split('/').pop() ?? lazyStrings.TransformersJsLoadingIndicator__model();
    if (modelName === undefined) return undefined;
    if (isLoadingFromCache.value) {
      return lazyStrings.TransformersJsLoadingIndicator__initializing_model({ modelName });
    }
    return lazyStrings.TransformersJsLoadingIndicator__downloading_model({ modelName });
  }
  case 'idle':
  case 'ready':
    return '';
  default: {
    const _ex: never = currentStatus;
    throw new Error(`Unhandled status: ${_ex}`);
  }
  }
});
const explanationText = computed(() => {
  if (isLoadingFromCache.value) {
    return lazyStrings.TransformersJsLoadingIndicator__loading_model_weights_into_browser_memory_for_local_inference();
  }
  return lazyStrings.TransformersJsLoadingIndicator__downloading_model_weights_from_hugging_face_this_only_happens_once_per_model();
});


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/0eea1ccb759d376dc6850e80ccb4026870cc6636a2829841cbd780378d3f79e4.js";
import "virtual:naidan-tailwind-css-module/4a284388d0d5f15140334afecc655910c02414d2d6c5858c90a507a7def47b12.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/f9004e4bacdf86afb575355f988f793b2afd745c3bac6d2f33d6f5ff0aadcaee.js";
</script>

<template>
  <div v-if="status === 'loading' || status === 'error'" class="animate-in fade-in" tw-class="duration-500">
    <!-- Full Mode (Integrated Chat Flow) -->
    <div v-if="mode === 'full'" tw-class="flex flex-col gap-4 p-5">
      <div tw-class="flex items-center gap-3">
        <div tw-class="w-8 h-8 rounded-xl flex items-center justify-center border border-blue-100 dark:border-blue-900/30 bg-blue-50/50 dark:bg-blue-900/20 shadow-sm">
          <BrainCircuitIcon tw-class="w-4 h-4 text-blue-500" />
        </div>
        <div tw-class="flex-1 min-w-0">
          <div tw-class="flex items-center justify-between mb-2">
            <div tw-class="flex flex-col">
              <span tw-class="text-[10px] font-bold text-blue-600 dark:text-blue-400 tracking-wider">
                {{ statusText }}
              </span>
              <span tw-class="text-[9px] text-gray-400 font-medium">
                {{ explanationText }}
              </span>
            </div>
            <span tw-class="text-[10px] font-bold text-blue-500/70 tabular-nums self-start mt-0.5">{{ progress }}%</span>
          </div>
          <div tw-class="h-1 w-full bg-gray-100 dark:bg-gray-800 rounded-full overflow-hidden">
            <div
              :tw-class="['h-full transition-all duration-500 ease-out', status === 'error' ? 'bg-red-500' : 'bg-blue-500 dark:bg-blue-400']"
              :style="{ width: progress + '%' }"
            ></div>
          </div>
        </div>
      </div>

      <!-- Feature Badges (Why we wait) -->
      <div v-if="status !== 'error'" tw-class="ml-11 flex flex-wrap gap-3">
        <div tw-class="flex items-center gap-1.5 text-[9px] font-bold text-gray-400 tracking-tight">
          <ShieldCheckIcon tw-class="w-3 h-3 text-green-500/70" />
          {{ lazyStrings.TransformersJsLoadingIndicator__on_device_execution() }}
        </div>
      </div>

      <div v-if="status === 'error' && error" tw-class="ml-11 p-3 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800 rounded-xl text-[10px] text-red-600 dark:text-red-400 font-medium leading-relaxed flex items-start gap-2">
        <AlertTriangleIcon tw-class="w-3.5 h-3.5 shrink-0" />
        {{ error }}
      </div>
    </div>

    <!-- Compact Mode (Fallback) -->
    <div v-else tw-class="flex items-center gap-2 text-blue-600 dark:text-blue-400">
      <BrainCircuitIcon tw-class="w-3 h-3 animate-pulse" />
      <span tw-class="text-[10px] font-bold">{{ progress }}%</span>
    </div>
  </div>
</template>
